'use strict';
const $ = s => document.querySelector(s);
const API=(window.MP3_API||'').replace(/\/$/,'');
let sound=false, busy=false;
function tone(){if(!sound)return;try{const C=window.AudioContext||window.webkitAudioContext;const c=new C();const o=c.createOscillator(),g=c.createGain();o.type='square';o.frequency.value=660;g.gain.value=.025;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.09);o.onended=()=>c.close();}catch{}}
function readHistory(){try{return JSON.parse(localStorage.getItem('mp3-history')||'[]').filter(x=>typeof x.title==='string'&&typeof x.created==='number').slice(0,20)}catch{return []}}
function saveHistory(items){try{localStorage.setItem('mp3-history',JSON.stringify(items))}catch{}}
function showView(view){if(view==='converter'){$('#window-content').hidden=false;$('#converter').hidden=false;}$('#history').hidden=view!=='history';$('#help').hidden=view!=='help';document.querySelectorAll('nav button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='history')renderHistory();if(view!=='converter')$('#'+view).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});tone()}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'♫ Som: ligado':'♫ Som: desligado';$('#sound').setAttribute('aria-pressed',String(sound));tone()};
$('#minimize').onclick=()=>{$('#window-content').hidden=!$('#window-content').hidden;$('#minimize').setAttribute('aria-label',$('#window-content').hidden?'Restaurar conversor':'Minimizar conversor')};
$('#maximize').onclick=()=>$('#converter').classList.toggle('expanded');$('#start').onclick=()=>{showView('converter');$('#url').focus()};
$('#change-wallpaper').onclick=()=>{document.body.classList.toggle('teal');try{localStorage.setItem('mp3-wallpaper',document.body.classList.contains('teal')?'teal':'clouds')}catch{}};
try{document.body.classList.toggle('teal',localStorage.getItem('mp3-wallpaper')==='teal')}catch{}
function clock(){$('#clock').textContent=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}clock();setInterval(clock,30000);
function message(text,error=false,loading=false){const s=$('#status');s.hidden=false;s.className='status-panel'+(error?' error':'');s.textContent=text;if(loading){const p=document.createElement('div');p.className='progress';p.setAttribute('aria-label','Conversão em andamento');s.append(p)}$('#status-label').textContent=error?'● Atenção':loading?'● Processando áudio…':'● Pronto';}
$('#paste').onclick=async()=>{try{$('#url').value=await navigator.clipboard.readText();$('#url').focus();tone()}catch{message('Para colar, toque e segure no campo do link e selecione “Colar”.')}};
function videoId(raw){try{const u=new URL(raw);if(!['https:','http:'].includes(u.protocol)||u.username||u.password)return null;let id;if(u.hostname==='youtu.be')id=u.pathname.slice(1).split('/')[0];else if(['youtube.com','www.youtube.com','m.youtube.com','music.youtube.com'].includes(u.hostname)){id=u.pathname==='/watch'?u.searchParams.get('v'): /^\/(shorts|embed|live)\//.test(u.pathname)?u.pathname.split('/')[2]:null;}return /^[\w-]{11}$/.test(id||'')?id:null}catch{return null}}
async function request(path,options={}){const ctrl=new AbortController();const timeout=setTimeout(()=>ctrl.abort(),75000);try{const r=await fetch(API+path,{...options,signal:ctrl.signal});let data;try{data=await r.json()}catch{throw new Error('O serviço não respondeu como esperado. Tente novamente em instantes.')}if(!r.ok)throw new Error(data.error||'Não foi possível converter este vídeo.');return data;}finally{clearTimeout(timeout)}}
$('#convert-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const id=videoId($('#url').value.trim());const file=$('#video-file').files[0];if(file&&file.size>50*1024*1024){message('O arquivo deve ter até 50 MB.',true);return}if(!file&&!id){message('Esse link não parece ser de um vídeo do YouTube. Confira o endereço e tente de novo.',true);return}if(!API&&location.hostname.endsWith('chatgpt.site')){message('O serviço de conversão ainda não foi ativado. A interface está pronta, mas os downloads dependem da conexão com o servidor.',true);return}busy=true;$('#convert').disabled=true;$('#convert').textContent='Aguarde…';$('#result').hidden=true;message('Conectando ao conversor… Na primeira vez, isso pode levar cerca de um minuto.',false,true);tone();const quality=$('input[name="quality"]:checked').value;try{let job=file?await request('/api/uploads?quality='+quality,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file}):await request('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({video_id:id,quality})});const end=Date.now()+360000;while(job.status!=='ready'){if(job.status==='failed')throw new Error(job.error||'Não foi possível baixar este vídeo.');if(Date.now()>end)throw new Error('A conversão levou mais tempo que o esperado. Tente novamente mais tarde.');message(job.status==='converting'?'Convertendo o áudio para MP3…':'Baixando o áudio do vídeo…',false,true);await new Promise(r=>setTimeout(r,2000));job=await request('/api/jobs/'+encodeURIComponent(job.id));}const url=API+'/api/download/'+encodeURIComponent(job.id);$('#file-title').textContent=job.title+'.mp3';$('#file-meta').textContent='MP3 • '+quality+' kbps • disponível por 15 minutos';$('#download').href=url;$('#result').hidden=false;message('Seu MP3 está pronto. Toque em “Baixar MP3” para salvar.');saveHistory([{title:job.title,quality,created:Date.now(),url},...readHistory()].slice(0,20));tone();}catch(err){message(err.name==='AbortError'?'O servidor está demorando a responder. Aguarde um minuto e tente novamente.':err instanceof TypeError?'Não foi possível conectar ao conversor. Confira sua internet e tente novamente.':err.message,true)}finally{busy=false;$('#convert').disabled=false;$('#convert').textContent='♫ Converter para MP3'}};
function renderHistory(){const list=$('#history-list');list.replaceChildren();const items=readHistory();if(!items.length){const p=document.createElement('p');p.textContent='Sua pasta está vazia. Os MP3s convertidos aparecerão aqui.';list.append(p)}for(const item of items){const row=document.createElement('div');row.className='history-item';const info=document.createElement('div');const t=document.createElement('strong');t.textContent='♫ '+item.title;const m=document.createElement('small');m.textContent=item.quality+' kbps • '+new Date(item.created).toLocaleDateString('pt-BR');info.append(t,m);row.append(info);if(Date.now()-item.created<15*60*1000){try{const u=new URL(item.url,location.origin);if(u.origin===(API||location.origin)&&/^\/api\/download\/[a-f0-9]{32}$/.test(u.pathname)){const a=document.createElement('a');a.textContent='Baixar';a.href=u.href;a.className='button';row.append(a)}}catch{}}else{const expired=document.createElement('small');expired.textContent='Expirado';row.append(expired)}list.append(row)}}
$('#clear-history').onclick=()=>{saveHistory([]);renderHistory()};

$('#clear-file').onclick=()=>{$('#video-file').value=''};
